**Creating InDesign script**

I need to write an ExtendScript (.jsx) to convert a facing-pages InDesign document into a single-page document while keeping margins and master associations intact. I'll set `documentPreferences.facingPages` to false. This means I have to change page sizes to match the spread width. I realize that converting from facing to non-facing might affect margins, so I need to address that. I may have to duplicate master spreads into single-page masters and reassign them. It’s quite complex, but I’ll aim to provide an optimized script. I'll ensure to include comments in the output.
[/Thinking]

```javascript
﻿/**
 *  FlattenSpreadsToSinglePages.jsx
 *
 *  Transforms a facing‑pages (spreads) InDesign document into a
 *  single‑page document, while preserving:
 *   - Original page size
 *   - Margins (inner/outer -> left/right)
 *   - Layout and coordinates of page items
 *   - Master page assignments (each original side of a spread gets its own master)
 *
 *  Usage:
 *   1. Open your document.
 *   2. Run this script from: File > Scripts > Browse…
 *   3. The script operates on the active document.
 *
 *  Notes:
 *   - The script creates a new document and copies pages into it.
 *   - This is safer than trying to mutate the existing document in place.
 *   - It works with multiple master spreads.
 */

(function () {
    // Ensure we have an open document
    if (app.documents.length === 0) {
        alert("No document open. Please open a document and run the script again.");
        return;
    }

    var sourceDoc = app.activeDocument;
    app.scriptPreferences.userInteractionLevel = UserInteractionLevels.interactWithAll;

    //========================================================
    // Helpers
    //========================================================

    /**
     * Clone margin preferences from a page or spread to a new marginPref object.
     */
    function cloneMarginPrefs(srcMarginPrefs, dstMarginPrefs) {
        dstMarginPrefs.top    = srcMarginPrefs.top;
        dstMarginPrefs.bottom = srcMarginPrefs.bottom;
        dstMarginPrefs.left   = srcMarginPrefs.left;
        dstMarginPrefs.right  = srcMarginPrefs.right;
        dstMarginPrefs.columnCount  = srcMarginPrefs.columnCount;
        dstMarginPrefs.columnGutter = srcMarginPrefs.columnGutter;
    }

    /**
     * Return a simple unique key for a master page used for mapping.
     * We combine the master spread name and side (Left/Right/Single).
     */
    function masterSideKey(masterPage) {
        var side = masterPage.side; // PageSideOptions.LEFT_HAND / RIGHT_HAND / SINGLE_SIDED
        var sideName;
        switch (side) {
            case PageSideOptions.LEFT_HAND:  sideName = "L"; break;
            case PageSideOptions.RIGHT_HAND: sideName = "R"; break;
            default:                         sideName = "S"; break;
        }
        return masterPage.appliedMaster.name + "__" + sideName;
    }

    /**
     * Copy all page items from sourcePage to destPage, preserving
     * geometric bounds and layering order.
     */
    function copyPageItems(sourcePage, destPage) {
        // Use a temporary group-and-duplicate pattern to keep relative positions.
        // More robust than copying individually in some layouts.
        if (sourcePage.pageItems.length === 0) return;

        var tempGroup = sourcePage.pageItems.everyItem().group();
        tempGroup.duplicate(destPage);
        tempGroup.ungroup();
    }

    //========================================================
    // Prepare new document
    //========================================================

    var docPrefs   = sourceDoc.documentPreferences;
    var pageWidth  = docPrefs.pageWidth;
    var pageHeight = docPrefs.pageHeight;

    // Create new single-page document (no facing pages)
    var newDoc = app.documents.add();
    var newDocPrefs = newDoc.documentPreferences;

    // Basic document setup copied from source
    newDocPrefs.pageWidth         = pageWidth;
    newDocPrefs.pageHeight        = pageHeight;
    newDocPrefs.pageOrientation   = docPrefs.pageOrientation;
    newDocPrefs.intent            = docPrefs.intent;
    newDocPrefs.facingPages       = false;
    newDocPrefs.pagesPerDocument  = 1; // we'll add more as needed
    newDoc.viewPreferences.rulerOrigin = sourceDoc.viewPreferences.rulerOrigin;

    // Remove the default first page in newDoc (we will re-create pages)
    while (newDoc.pages.length > 0) {
        newDoc.pages[0].remove();
    }

    //========================================================
    // Master pages handling
    //========================================================

    /**
     * Strategy:
     * For each used side of each master spread (Left / Right / Single),
     * create a dedicated single-page master in newDoc.
     *
     * Then, when copying each page, assign the corresponding master
     * so that reference to master elements is kept.
     */

    var masterMap = {}; // key: original master+side => new master page

    function createSingleSideMaster(srcMasterPage) {
        var key = masterSideKey(srcMasterPage);
        if (masterMap[key]) return masterMap[key];

        var srcMasterSpread = srcMasterPage.appliedMaster;
        var baseName = srcMasterSpread.name;
        var sideSuffix;

        switch (srcMasterPage.side) {
            case PageSideOptions.LEFT_HAND:  sideSuffix = "_L"; break;
            case PageSideOptions.RIGHT_HAND: sideSuffix = "_R"; break;
            default:                         sideSuffix = "_S"; break;
        }

        var newMasterName = baseName + sideSuffix;

        var newMaster = newDoc.masterSpreads.add();
        newMaster.name = newMasterName;

        // Ensure a single page on this master
        while (newMaster.pages.length > 1) {
            newMaster.pages.lastItem().remove();
        }
        var newMasterPage = newMaster.pages[0];

        // Set same size and margins
        newMasterPage.bounds = srcMasterPage.bounds;
        cloneMarginPrefs(srcMasterPage.marginPreferences, newMasterPage.marginPreferences);

        // Copy master items
        // To do this robustly, temporarily override applied master on a dummy document page
        // But we can duplicate directly from the master page
        if (srcMasterPage.pageItems.length > 0) {
            var grp = srcMasterPage.pageItems.everyItem().duplicate(newMasterPage, ElementPlacement.INSIDE);
            // If 'grp' is a collection, we don’t need to group/ungroup; they come in as items.
            // Just leave as-is.
        }

        masterMap[key] = newMasterPage;
        return newMasterPage;
    }

    // Prebuild master map for all master pages that are actually applied somewhere
    var usedMasters = {};
    var i, p;

    for (i = 0; i < sourceDoc.pages.length; i++) {
        var pg = sourceDoc.pages[i];
        if (pg.appliedMaster !== null && pg.appliedMaster instanceof Page) {
            var mKey = masterSideKey(pg);
            usedMasters[mKey] = pg;
        }
    }

    for (var k in usedMasters) {
        if (usedMasters.hasOwnProperty(k)) {
            createSingleSideMaster(usedMasters[k]);
        }
    }

    //========================================================
    // Copy pages from sourceDoc to newDoc
    //========================================================

    app.doScript(function () {
        for (i = 0; i < sourceDoc.pages.length; i++) {
            var srcPage = sourceDoc.pages[i];

            // Add a new page in the new document
            var newPage = newDoc.pages.add(LocationOptions.AT_END);

            // Match size and margins
            newPage.bounds = srcPage.bounds;
            cloneMarginPrefs(srcPage.marginPreferences, newPage.marginPreferences);

            // Apply corresponding master page (if any)
            if (srcPage.appliedMaster !== null && srcPage.appliedMaster instanceof Page) {
                var mk = masterSideKey(srcPage);
                if (masterMap[mk]) {
                    newPage.appliedMaster = masterMap[mk].parent; // masterSpreads
                }
            } else {
                newPage.appliedMaster = null;
            }

            // Copy page items (non-master items)
            copyPageItems(srcPage, newPage);

            // Preserve ruler origin-based coordinates by matching spread bounds
            // (we already matched page bounds; in most cases this is sufficient.)
        }

        // Optional: match document metadata, swatches, styles etc.
        // (Most of these are automatically created/configured already,
        // but if needed you could deep-clone them here.)

    }, ScriptLanguage.JAVASCRIPT, undefined, UndoModes.ENTIRE_SCRIPT, "Flatten Spreads to Single Pages");

    alert("Conversion complete.\nA new single-page document has been created.");
})();
